import math

def max_festival_area(N, K):
    if N < 2 * K:
        return 0.00

    X = [0 for _ in range(1000)]
    Y = [0 for _ in range(1000)]

    for _ in range(K):
        x, y = (map(int, input().split()))
        X[x] += 1
        Y[y] += 1

    max_area = 0.00

    for i in range(2, N + 1):
        if X[i - 2] + X[i] - 1 < 2:
            break
        for j in range((i - 1) - i % 2, N + 1, i):
            tmp_area = (math.sqrt((X[i - 1] - X[i + i // 2 - 1]) ** 2 + (Y[i] - Y[i + i // 2]) ** 2) 
                        + math.sqrt((X[i - 1] - X[i + i // 2 + 1]) ** 2 + (Y[i] - Y[i + i // 2 + 2]) ** 2)) // 2
            max_area = max(max_area, tmp_area)

