import sys

def min_drivers(n, m, edges, start, end):
    # Create adjacency list representation of the graph
    graph = [[] for _ in range(n)]
    for ui, vi in edges:
        graph[ui-1].append((vi-1, 1) if ui < vi else (vi-1, -1))

    from collections import deque
    parents = [-1] * n
    visited = [0] * n
    drivers = 0

    def dfs(v):
        nonlocal drivers
        if visited[v]:
            return False
        visited[v] = -1
        if parents[v] == -1:
            drivers += 1
        for neighbor, depart_cost in graph[v]:
            if parents[neighbor] == -1:
                parents[neighbor] = v
            if parents[neighbor] != -1:
                if depart_cost == -1 and parents[neighbor] < v:
                    dfs(parents[neighbor])
            else:
                dfs(neighbor)
        return True

    probes = deque([start-1])
    for _ in range(n):
        if not dfs(start-1):
            return drivers if not dfs(end-1) else -1
        while probes[0][1]:
            if parents[probes[0]] != -1:
                dfs(parents[probes[0]]-1)
            del probes[0]
        while probes[0][1]:
            visited[probes[0][0]] += 1
            probes.append(probes.popleft())
    dfs(end-1)
    return drivers if all(v == -1 for v in range(n)) else -1

