import sys

def combinations(n, k):
    # Return the number of ways to choose k items from n items
    if k > n:
        return 0
    if k == 0:
        return 1
    # The formula to calculate combinations C(n, k) is n! / (k! * (n-k)!)
    return factorial(n) / (factorial(k) * factorial(n - k))

def factorial(n):
    # Compute the factorial of n
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def solve(n):
    total_edges = n - 1  # Since there are n-1 edges in a tree with n vertices
    ways = combinations(total_edges, 2) * 2 + total_edges  # 2*ways + total_edges = total_choices
    return ways % 998244353

