def awesome_substrings(binary_string):
    count = 0
    length = 0
    ones_count = binary_string.count('1')

    if ones_count == 0:
        return 0

    for i in range(len(binary_string)):
        if binary_string[i] == '1':
            length += 1
        else:
            count += (length * (length + 1) // 2)
            if length % ones_count != 0:
                if binary_string[i-1] == '0':
                    count -= len(binary_string) - i - 1
                else:
                    count += ones_count - ((length - 1) % ones_count)
            length = 0

    if length != 0:
        count += (length * (length - 1) // 2)
        if length % ones_count != 0:
            if binary_string[-1] == '0':
                count -= len(binary_string) - length - 1
            else:
                count += ones_count - ((length - 1) % ones_count)

    return count

