# Function to find the maximum area of a convex k-gon
def max_festival_area(N, K, X, Y):
    if K > N - 1 or N < K:
        return 0.00

    max_area = 0.00

    for k in range(K, N):
        for j in range(k - K):
            i = k - j
            min_x = min(X[i], X[i-1])
            max_x = max(X[i], X[i-1])
            min_y = min(Y[i], Y[i-1])
            max_y = max(Y[i], Y[i-1])

            min_z = min(min_x, min_y)
            max_z = max(max_x, max_y)

            for p in range(K):
                if i < N and j < N and i < p <= j and j < p <= i - 1:
                    continue

                for q in range(K + 1, 2 * N):
                    if q < N and q <= p:
                        continue

                    temp_area = triangle_area(X[i-1], Y[i-1], X[i], Y[i]) + triangle_area(X[j-1], Y[j-1], X[0], Y[0]) - triangle_area(X[i-1], Y[i-1], X[q-1], Y[q-1]) - triangle_area(X[j-1], Y[j-1], X[q], Y[q])
                    if temp_area > max_area:
                        max_area = temp_area

            for j_att in range(j + 1, N):
                i = k + j - j_att
                min_x_att = min(X[i], X[i-1])
                max_x_att = max(X[i], X[i-1])
                min_y_att = min(Y[i], Y[i-1])
                max_y_att = max(Y[i], Y[i-1])

                temp_area_att = triangle_area(X[j-1], Y[j-1], X[0], Y[0]) + triangle_area(X[i-1], Y[i-1], X[max_x_att], Y[max_x_att]) - triangle_area(X[j-1], Y[j-1], X[p], Y[p]) - triangle_area(X[i-1], Y[i-1], X[p-1], Y[p-1])
                if temp_area_att >= max_area and (i == 0 or i != p):
                    max_area = temp_area_att

    return round(max_area, 2)

