import itertools

def bfs(graph, start, target, orders):
    visited = {start: float('inf')}
    queue = deque([(start, 0)])

    while queue:
        current, depth = queue.popleft()
        if current == target:
            return depth
        if current in visited:
            continue
        visited[current] = depth + 1

        for neighbor in graph[current]:
            if neighbor not in visited and (orders or neighbor != start):
                queue.append((neighbor, depth + 1))
        if neighbor == start and (orders or graph[current][target] == float('inf')):
            queue.append((target, depth + 1))

    return visited[target] if target in visited else float('inf')

