class RangeTree:
    def __init__(self, a):
        a.sort()
        self.ranges = []
        self.build(a)

    def build(self, a):
        a = sorted(a)
        self.ranges = [a[0]]
        for i in range(1, len(a)):
            if a[i] != self.ranges[-1]:
                self.ranges.append(a[i])
        return self.ranges

    def merge(self, i, j):
        return self.merge_for_range(i) + self.ranges[-1] - self.merge_for_range(j)

    def merge_for_range(self, i):
        if i == 0:
            return self.ranges[-1]
        return self.ranges[i-1]

    def query(self, rstart, rend):
        max_node = self.ranges[-1]
        for i in range(len(self.ranges) - 2, -1, -1):
            max_node = max(max_node, self.merge_for_range(i))
        if rend >= self.ranges[-1]:
            return rend - rstart
        if rend >= max_node:
            return rend - rstart + self.merge_for_range(len(self.ranges) - 1)
        if rend < rstart:
            return rstart - rend
        m = len(self.ranges) - 1
        while m > 0:
            m //= 2
            if rend < self.ranges[2 * m]:
                rend -= self.ranges[2 * m]
                m -= 1
        t = self.ranges[-1] - rend
        return rstart - m - 1 + t

