import sys

def min_orders(graph, start, end):
    if not graph or start == end:
        return -1

    # Initialize order storage for each vertex
    orders = [-1] * (max(graph) + 1)

    # BFS to find the shortest path
    queue = [(start, 0)]
    visited = {start}

    while queue:
        vertex, depth = queue.pop(0)

        for next_vertex in graph[vertex]:
            if next_vertex not in visited:
                queue.append((next_vertex, depth + 1))
                visited.add(next_vertex)

    # Check the very last potential order
    depth = visited.pop()

    for next_vertex in graph[end]:
        if next_vertex == start:
            continue
        if depth > orders[next_vertex]:
            return -1
        orders[next_vertex] = depth

    for vertex in orders.keys():
        if orders[vertex] == -1:
            return -1

    return len(orders)

