def solve_bags(n, s, a):
    if s % n != 0:
        return -1

    total = s
    current = 0
    arranged_bags = []

    for bag in a:
        if current + bag > s:
            break
        current += bag
        arranged_bags.append([bag, 0])

    current = total

    for i in range(n):
        if current < 0:
            return -1
        if i < n - 1:
            arranged_bags[i][1] += 1
            arranged_bags[i][0] = a[i + 1]
            continue
        for bag in a[i + 1:]:
            if current + bag > s:
                break
            current += bag
            arranged_bags[i][1] += 1
            arranged_bags[i][0] = bag

    if current != s:
        return -1

    return '\n'.join([' '.join(map(str, bag)) for bag in arranged_bags])

