MOD = 1000000007

def count_good_permutations(n, k):
    if n == k:
        return MOD%MOD
    if k > n:
        return 0

    if k == 0:
        return 1

    if k == 1:
        return (n*(MOD-1) - n*(MOD-2))/2  # Sum of (n-i) for i from 2 to n-1

    res = 0
    down = lambda x: MOD*(MOD-1-x+MOD) // (MOD-1-1)

