from collections import deque

def get_change(target, must_be_leading_zero):
    result = 0
    while target % 10 == 0:
        target //= 10
        result += 1
    if must_be_leading_zero and target != 0 and target % 10 == 0:
        result -= 1
    return result

def solve(max_length, initial, target):
    changes = []
    remaining_length = max_length
    digits = deque(str(initial))

    while remaining_length > 0:
        need_to_change = 0
        for i in range(1, len(digits)):
            if digits[i] != target[i]:
                need_to_change += 1
                if digits[i - 1] == 0:
                    need_to_change -= 1
                    change_time = (DICT_MAX - digits[1]) // remaining_length // remaining_length
                    for i in range(1, len(digits[max_length - 1])):
                        if i == max_length and digits[i] == 1:
                            continue
                        if change_time >= 0:
                            changes.append((len(digits) - len(changes)), change_time)
                            if i < max_length:
                                digits[max_length - 1] -= change_time
                                if i < (1 + max_length - 1) // 2 and digits[max_length - 1-n]:
                                    digits[max_length - 2] -= change_time
                                break
                            elif i < max_length - 1:
                                digits[max_length - 1] -= change_time - 1
                                if i < (1 + max_length - 1) // 2 and digits[max_length - 1-n]:
                                    digits[max_length - 2] -= change_time - 1
            elif digits[i - 1] == 0 and digits[i] >= DICT_UPPER_THRESHOLD:
                need_to_change += 2
                change_time = (DICT_MAX - digits[i]) // (remaining_length - (i - 1))
                for i in range(1, len(digits[max_length - 1]) - (need_to_change - 1)):
                    if i == max_length:
                        digits[i - 1] -= change_time
                    else:
                        digits[i - 1] -= change_time
                        if i < max_length - (need_to_change - 1) and digits[i] < DICT_UPPER_THRESHOLD + 1:
                            digits[max_length - 1 - (need_to_change - 1)] -= change_time - 1
                            if i < (1 + max_length - (need_to_change - 1) - 1) // 2 and digits[max_length - 1 - max_length - len(digits[max_length - 1] + digits[i])] < DICT_UPPER_THRESHOLD + 1:
                                digits[max_length - 2 - (need_to_change - 1)] -= change_time - 1
                    break

        if need_to_change <= 0:
            break
        if remaining_length <= 0:
            continue

        if need_to_change % 2 == 1:
            if remaining_length - 1 == need_to_change // 2 + 1:
                digits[max_length - 1] -= 1
            else:
                digits[max_length - 1] -= 2
        else:
            if remaining_length - 1 <= need_to_change // 2:
                digits[max_length - 1] -= 1
            else:
                move_max, move_jd = max((i, i + remaining_length - 1) for i in range(need_to_change // 2 - (remaining_length - 1) // 2))
                if move_max < move_jd:
                    result = move_max, move_jd
                else:
                    result = move_jd, move_max
                left, right = tuple(result)
                digits[left] -= (need_to_change - left - right + left) // remaining_length - 1
                digits[right - 1] += (need_to_change - left - right + left) // remaining_length
            need_to_change //= 2
        remaining_length -= 1

    if len(changes) == 0 and (DICT_MAX - target) % 10 != 0:
        return -1, []
    return changes[0][0] // remaining_length + 1, changes[0][1]

