        open_schedule.add(x)
        close_schedule.add(x)

    for _ in range(m):
        x, y, z = map(int, input().split())
        schedules.append((x, y, z))
        if x in open_schedule and x not in close_schedule:
            open_schedule.add(x)
        elif x in close_schedule and x not in open_schedule:
            close_schedule.add(x)

    for _ in range(k):
        x, y, z = map(int, input().split())
        schedules.append((x, y, z))

    return schedules, opened_trips, closed_trips

def check_schedule(opened, closed, schedule, query_month, query_day, query_second):
    if schedule in opened:
        return 'OPEN'
    if schedule in closed:
        return 'CLOSED'
    return 'UNKNOWN'

def process_queries(schedules, opened, closed, queries):
    results = []
    for query in queries:
        query_month, query_day, query_second = query
        query_schedule = (query_month, query_day, query_second)

        query_result = check_schedule(opened, closed, query_schedule, schedules, queries)

        if query_result == "INCORRECT":
            return "INCORRECT"
        results.append(query_result)

