from collections import defaultdict

def solve(n, s, a):
    bags = defaultdict(list)
    for ai in a:
        bags[0].append(ai)

    two_level = []
    three_level = []

    for i in range(1, n):
        for j in range(len(bags[i])):
            if len(bags[i-1]) - j > len(bags[i]) - j:
                two_level.append((i, "inner_two"))
            else:
                three_level.append((i, "inner_three"))
            break

    empty = []
    not_complete = []
    for i in range(n - 1):
        if bags[i] == []:
            empty.append(i + 1)
        else:
            not_complete.append(i)

    leftover = s - sum(bags[0])

    if leftover == 0:
        return " ".join(str(j + 1) for j in not_complete)
    elif leftover % 2 == 1 and leftover // 2 + leftover % 3 < len(two_level) + 1:
        return " ".join(str(j + 1) for j in two_level[:leftover // 2 + leftover % 3])
    elif leftover % 2 == 0 and leftover // 2 < len(three_level) + 1:
        return " ".join(str(j + 1) for j in three_level[:leftover // 2])
    else:
        return "-1"

