from collections import defaultdict
from itertools import permutations

def find_min_press_sequence(d, n, passwords):
    # Initialize the callback dictionary with empty lists
    callback = defaultdict(list)

    # Dictionary to keep track of transitions between button states
    transitions = defaultdict(list)

    # Apply the specified button configurations
    for password in passwords:
        prev = 0
        for i in range(d):
            if password[i] == '1':
                callbacks = list(callback[i])
                for j in callbacks:
                    transitions[(i, prev, j)].append(i)
                transitions[(prev, i, j)].append(i) if prev != i else None
                callbacks = callbacks + transitions[j]
                callback[i].extend(callbacks)
                prev = i

    # Recursive function to find the shortest sequence
    def find_min_sequence(depth, sequence, available_values):
        if depth == d:
            yield sequence
            return

        for button in available_values:
            if button in transitions[seq[-1]]:
                seq = sequence + [button]
                for next_button in transitions[seq[-1]][button]:
                    yield from find_min_sequence(depth + 1, seq, transitions[next_button])
                seq = sequence[:-1]

    seq = []
    for button in transitions[0]:
        if len(callback[button]) != len(passwords[0]) or 0 in transitions[button][button]:
            seq.append(button)

    min_sequence = None
    for transition_sequence in find_min_sequence(1, seq, transitions[1]):
        if min_sequence is None or len(str(transition_sequence)) < len(min_sequence):
            min_sequence = str(transition_sequence)

    min_presses = min_sequence.count('R') + 1
    return min_presses, min_sequence

