    for r1, r2 in allowed_roads:
        for comb in combinations([r1, r2], r=2):
            for c1, c2 in comb:
                length[c1], length[c2] = min([length[c1], length[c2]], 0), max(
                    [length[c1], length[c2]]
                ) + r1 + r2
    return min(length[start1], length[start2])

