        allowed_roads = combinations(roads, k)
        end = find_best(k, allowed_roads, start1, start2, end)

    paths = []
    for r1, r2 in allowed_roads:
        paths.append((start1, start2 if r1 else end, start1 + r1 + r2, r2))

    return (len(paths), *paths)

