from collections import Counter

def paintable_tiles(n, q, colors):
    count = Counter()
    result = []
    for i in range(n):
        for j in range(n):
            color = colors[i][j]
            count[color] += 1
            if len(count) <= max(1, q):
                result.append(1)
            else:
                if color in count:
                    count[color] -= 1
                    if count[color] == 0:
                        del count[color]
                else:
                    del count[color][0]  # Remove the least common color
    return result

n, q = map(int, input().split())
matrix = []
for _ in range(n):
    matrix.append(list(map(int, input().split())))

results = paintable_tiles(n, q, matrix)
for r in results:
    print(r)
